// NRGBA for a PNG with alpha, and this is a copy for everything else --
// including the JPEG case, where the alpha it fills in is opaque, which is
// what a JPEG means.
func nrgbaRefs(in []image.Image) ([]*image.NRGBA, error) {
	if len(in) == 0 {
